/**
 * Client-safe media index (videos, clips, hero sources, poster URLs).
 * Generated by scripts/build-client-media.mjs from media.json.
 */
import data from '@/content/media.client.json';

export type LoopEntry = { mp4: string; webm: string; poster: string; width: number; height: number; blurDataURL: string; cuts: number[] };
export type FullEntry = { location: 'public' | 'blob'; mp4: string; webm: string | null; width: number; height: number; duration: number };
export type VideoEntry = {
  orientation: 'landscape' | 'portrait' | 'square';
  aspect: number;
  duration: number;
  loop: LoopEntry;
  full?: FullEntry;
};
export type ClipEntry = Omit<LoopEntry, 'cuts'>;

type ClientIndex = {
  videos: Record<string, VideoEntry>;
  clips: Record<string, ClipEntry>;
  posters: Record<string, string>;
  hero: { desktop: Record<string, string>; mobile: Record<string, string> };
};

export const cmedia = data as unknown as ClientIndex;

export function clip(key: string): ClipEntry {
  const e = cmedia.clips[key];
  if (!e) throw new Error(`[media] unknown clip "${key}"`);
  return e;
}

const BLOB_BASE = (process.env.NEXT_PUBLIC_MEDIA_BLOB_BASE || '').replace(/\/$/, '');

/** Full-length cut URLs, or null when it lives on Vercel Blob and Blob isn't configured yet. */
export function fullVideo(key: string) {
  const v = cmedia.videos[key];
  const f = v?.full;
  if (!f) return null;
  const poster = cmedia.posters[`${key}-still`] ?? v.loop.poster;
  if (f.location === 'public') return { ...f, webm: f.webm ?? undefined, poster };
  if (!BLOB_BASE) return null;
  return { ...f, mp4: `${BLOB_BASE}/${f.mp4}`, webm: f.webm ? `${BLOB_BASE}/${f.webm}` : undefined, poster };
}
